// And groups predicates with the AND operator between them.
func And(predicates ...predicate.AttackReport) predicate.AttackReport {
	return predicate.AttackReport(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.AttackReport) predicate.AttackReport {
	return predicate.AttackReport(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.AttackReport) predicate.AttackReport {
	return predicate.AttackReport(sql.NotPredicates(p))
}
